with open(output_path, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    writer.writerow(["id", "name", "category", "description"])
    for i, (name, category, desc) in enumerate(products, start=1):
        writer.writerow([i, name, category, desc])

